//! Fixed-capacity ring buffer (circular queue).

/// A fixed-capacity FIFO ring buffer.
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,   // index to read from
    tail: usize,   // index to write to
    len: usize,
    capacity: usize,
}

impl<T> RingBuffer<T> {
    /// Create a ring buffer with given capacity.
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be > 0");
        let data = (0..capacity).map(|_| None).collect();
        RingBuffer { data, head: 0, tail: 0, len: 0, capacity }
    }

    /// Push value to the back. Returns Err if full.
    pub fn push(&mut self, value: T) -> Result<(), T> {
        unimplemented!()
    }

    /// Pop value from the front. Returns None if empty.
    pub fn pop(&mut self) -> Option<T> {
        unimplemented!()
    }

    /// Return true if buffer is full.
    pub fn is_full(&self) -> bool {
        unimplemented!()
    }

    /// Return true if buffer is empty.
    pub fn is_empty(&self) -> bool {
        unimplemented!()
    }

    /// Return the number of elements currently stored.
    pub fn len(&self) -> usize {
        self.len
    }
}

impl<T: Clone> Iterator for RingBuffer<T> {
    type Item = T;
    fn next(&mut self) -> Option<T> {
        self.pop()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_push_pop_fifo() {
        let mut rb: RingBuffer<i32> = RingBuffer::new(4);
        rb.push(1).unwrap();
        rb.push(2).unwrap();
        rb.push(3).unwrap();
        assert_eq!(rb.pop(), Some(1));
        assert_eq!(rb.pop(), Some(2));
        assert_eq!(rb.pop(), Some(3));
        assert_eq!(rb.pop(), None);
    }

    #[test]
    fn test_full_returns_err() {
        let mut rb: RingBuffer<i32> = RingBuffer::new(2);
        rb.push(1).unwrap();
        rb.push(2).unwrap();
        assert!(rb.is_full());
        assert!(rb.push(3).is_err());
    }

    #[test]
    fn test_wrap_around() {
        let mut rb: RingBuffer<i32> = RingBuffer::new(3);
        rb.push(1).unwrap();
        rb.push(2).unwrap();
        rb.push(3).unwrap();
        rb.pop(); // remove 1, head moves
        rb.push(4).unwrap(); // wraps around
        assert_eq!(rb.pop(), Some(2));
        assert_eq!(rb.pop(), Some(3));
        assert_eq!(rb.pop(), Some(4));
    }

    #[test]
    fn test_is_empty() {
        let mut rb: RingBuffer<i32> = RingBuffer::new(3);
        assert!(rb.is_empty());
        rb.push(1).unwrap();
        assert!(!rb.is_empty());
        rb.pop();
        assert!(rb.is_empty());
    }

    #[test]
    fn test_iterator() {
        let mut rb: RingBuffer<i32> = RingBuffer::new(4);
        rb.push(10).unwrap();
        rb.push(20).unwrap();
        rb.push(30).unwrap();
        let v: Vec<i32> = rb.collect();
        assert_eq!(v, vec![10, 20, 30]);
    }
}
